const r=JSON.parse(load("shakerRead").content[0].text); const frac=s=>s.includes("/")?s.split("/").map(Number).reduce((a,b)=>a/b):Number(s);
const ev=r.data.document.split("\n").filter(x=>x.startsWith("EVENT ")).map((s,i)=>{const t=s.split(" ");const at=frac(t[3]);return {id:t[1],at,cell:Math.round(at*512),i,offset:at-i/2};});
const median=a=>{const b=[...a].sort((a,b)=>a-b);return (b[(b.length-1)>>1]+b[b.length>>1])/2;};
const even=median(ev.filter(x=>x.i%2===0).map(x=>x.offset)),odd=median(ev.filter(x=>x.i%2).map(x=>x.offset));
store("shakerEvents",ev);store("shakerCenters",{even,odd});
text({even,odd,swingPercent:(.5+odd-even)*100,offsets:ev.map(x=>({hit:x.i+1,offset:+x.offset.toFixed(4)}))});

const r=JSON.parse(load("shakerRead").content[0].text),ev=load("shakerEvents"),centers=load("shakerCenters");
const gcd=(a,b)=>b?gcd(b,a%b):a; const fraction=n=>{const g=gcd(n,512); return n%512===0?String(n/512):`${n/g}/${512/g}`;};
const edits=ev.map(e=>{const center=(e.i%2?centers.odd:centers.even)*512;const resid=Math.max(-6,Math.min(6,(e.offset*512-center)*.35));const cell=e.i===0?0:Math.round(e.i*256+center+resid);return {...e,newCell:cell};}).filter(e=>e.cell!==e.newCell);
const doc=`DOC ghostnote-document 1.0 patch\nBASE ${JSON.stringify(r.authority.base)}\nFIELDS id clip at duration pitch velocity channel mute\n`+edits.map(e=>`UPDATE ${e.id} {"at":"${fraction(e.newCell)}"}`).join("\n");
store("shakerPatch",doc); store("shakerEdits",edits);
text({changedHits:edits.length,maxMoveMs:Math.max(...edits.map(e=>Math.abs(e.newCell-e.cell)))/512*60000/132});
text(await tools.mcp__ghostnote__edit_launcher_clip({trackId:r.target.trackId,row:0,document:doc,dryRun:true}));

